export function getClasseVoies(c){return (COF_CLASSES[c]&&COF_CLASSES[c].voiesData||[]).map(function(v){return {nom:v.nom,caps:v.caps.map(function(x){return Object.assign({},x);})};});}
// Table des modificateurs COF
export function cofMod(score){
  const s=parseInt(score)||0;
  if(s<=3) return -4;
  if(s<=5) return -3;
  if(s<=7) return -2;
  if(s<=9) return -1;
  if(s<=11) return 0;
  if(s<=13) return 1;
  if(s<=15) return 2;
  if(s<=17) return 3;
  if(s<=19) return 4;
  return 5;
}
export function modStr(m){return m>=0?'+'+m:String(m);}

export function getClasseEquip(c){return COF_CLASSES[c]&&COF_CLASSES[c].equipDepart||[];}
