// ── Helpers purs partagés (parsing modificateurs / dés) ──
export function parseMod(s){ const n=parseInt(String(s).replace(/[^0-9\-+]/g,'')); return isNaN(n)?0:n; }
export function dvMax(dv){ const m={'D4':4,'D6':6,'D8':8,'D10':10,'D12':12}; return m[String(dv).toUpperCase()]||6; }
export function parseAtt(s){ const n=parseInt(String(s).replace(/[^0-9-]/g,'')); return isNaN(n)?0:n; }
export function fmtAtt(n){ return n>=0?'+'+n:String(n); }
export function isPrestige(voieNom){ return /prestige/i.test(voieNom); }
export function capCost(rang, voieNom){
  if(isPrestige(voieNom)) return 2;
  const r=parseInt(rang.replace('R',''));
  return r<=2?1:2;
}
